<script setup lang="ts">
import type { Content, ContentType, Page } from '~/types'
import { sectionOf, dateText } from '~/utils/site'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '工作台' })
const { account } = useAuth()
type Data = { counts: { contentType: ContentType; total: number; drafts: number; published: number; trash: number }[]; drafts: Page<Content>; activity: { id: number; action: string; createdAt: string; targetType: string; targetId: number }[] }
const { data, error, refresh } = await useFetch<Data>('/api/admin/dashboard')
const total = (key: 'total' | 'drafts' | 'published' | 'trash') => data.value?.counts.reduce((sum, row) => sum + row[key], 0) || 0
</script>
<template><div><section class="studio-welcome"><div><span class="eyebrow">A LITTLE SPACE FOR YOUR IDEAS</span><h1>你好，{{ account?.displayName || '菜牙' }}。<br>今天也认真记录。</h1><p>整理想法，收藏发现，让这个小小的内容空间慢慢生长。</p><div class="admin-actions"><NuxtLink class="button primary" to="/admin/editor/new?type=article">＋ 写文章</NuxtLink><NuxtLink class="button" to="/admin/editor/new?type=work">添加作品</NuxtLink></div></div><div class="studio-art" aria-hidden="true"><div class="orbit" /><div class="leaf" /><div class="leaf second" /><small>WRITE A LITTLE.<br>GROW A LITTLE.</small></div></section><p v-if="error" role="alert" class="form-error">工作台加载失败。<button @click="refresh()">重试</button></p><div class="metric-grid"><NuxtLink v-for="m in [{ name: '草稿箱', key: 'drafts', note: '继续那些未完成的想法', path: '/admin/articles?status=draft' }, { name: '已发布内容', key: 'published', note: '与世界分享的每一份记录', path: '/admin/articles?status=published' }, { name: '内容总数', key: 'total', note: '一点一滴，慢慢积累', path: '/admin/articles' }, { name: '回收站', key: 'trash', note: '暂时收起，随时可以恢复', path: '/admin/articles?status=trash' }]" :key="m.key" :to="m.path" class="metric-card"><span>{{ m.name }}</span><strong>{{ String(total(m.key as 'total')).padStart(2, '0') }}</strong><small>{{ m.note }}</small></NuxtLink></div><div class="dashboard-grid"><section class="studio-panel"><div class="panel-heading"><h2>继续编辑</h2><NuxtLink to="/admin/articles?status=draft">全部草稿 ↗</NuxtLink></div><NuxtLink v-for="draft in data?.drafts.items" :key="draft.id" :to="`/admin/editor/${draft.id}`" class="draft-row"><span class="draft-icon">{{ sectionOf(draft.contentType).icon }}</span><div><strong>{{ draft.title || '未命名草稿' }}</strong><small>{{ sectionOf(draft.contentType).label }} · {{ dateText(draft.updatedAt) }}</small></div><span>继续编辑 →</span></NuxtLink><div v-if="!data?.drafts.items.length" class="admin-empty">还没有草稿，开始新的记录吧。</div></section><section class="studio-panel"><h2>内容花园</h2><NuxtLink v-for="row in data?.counts" :key="row.contentType" :to="`/admin/${sectionOf(row.contentType).path}`" class="content-count-row"><span>{{ sectionOf(row.contentType).label }}</span><span>{{ row.published }} 已发布 · {{ row.drafts }} 草稿</span><b>{{ row.total }}</b></NuxtLink><p v-if="!data?.counts.length" class="admin-empty">每一个栏目，都在等待你的第一份记录。</p></section></div><div class="dashboard-grid"><section class="studio-panel"><div class="panel-heading"><h2>最近操作</h2><NuxtLink to="/admin/logs">查看全部 ↗</NuxtLink></div><div v-for="log in data?.activity" :key="log.id" class="activity-row"><time>{{ dateText(log.createdAt) }}</time><span>{{ log.action }}</span><small>#{{ log.targetId }}</small></div></section><section class="studio-panel studio-note"><span class="eyebrow">KEEP YOUR WORDS SAFE</span><h2>让记录有归处，也有备份。</h2><p>内容发布后会保留冻结版本。修改先保存为工作稿，确认发布后才会更新前台。</p><NuxtLink to="/admin/settings" class="button">网站设置与备份说明 ↗</NuxtLink><NuxtLink to="/admin/analytics" class="text-link">查看真实访问统计 →</NuxtLink></section></div></div></template>
